/// **Runs on the server thread** (`AgentServer.offMainTools`), `import_media`'s
/// shape and never `transcribe`'s synchronous body: the recorder's every
/// callback lands on MAIN, so a main-thread wait would deadlock, and a
/// recording of up to ten minutes is not a thing the UI may freeze for. Every
/// document touch is an `onMain` hop; every wait is a `DispatchSemaphore`
/// signalled from main with an `AgentBox` carrying the answer across.
///
/// **The refusal ORDER is the contract** (`transcribe`'s rule): the caller's
/// own mistakes FIRST, so they stay reachable with no grant — `seconds`
/// missing or outside 1…600, then `source` (its value; the camera's
/// strangers, `camera_layout` and `camera_cutout` among them, spec §11
/// CO-83 (a); for `voice_over`
/// the screen-only arguments given, `keys`, `cursor` and the polish's three
/// among them, then `microphone: false`), `display` with `window`, a `rate` or `size` outside the
/// vocabulary, a `keys` outside its vocabulary (spec §11 CU-62), a `cursor`
/// outside its vocabulary (spec §11 CU-36 (e)), `enhance:
/// true` without a microphone and then with `place: false` (spec §11 AU-69),
/// `auto_zoom`, `shortcut_overlays` and `speed_up_typing` in that order, each
/// with `place: false` and the last two without `keys: "shortcuts"` (road map
/// creator-jobs CU10, spec §11 CU-102 (b)), a `camera_layout` outside its
/// vocabulary and then, with `place: false`, a `camera_layout` given and a
/// `camera_cutout: true` (CO8, spec §11 CO-83 (b)),
/// `microphone: true` (implied by a voice-over) with the Microphone grant
/// absent (the status WORD in the sentence), `keys: "shortcuts"` with the
/// Input Monitoring grant absent (CU-3's sentence, read and never
/// requested), and a `project` naming nothing
/// open, answered by `target(_:)`'s own sentence and never turned into a
/// fresh document. A voice-over stops there: it reads no other grant and
/// looks nothing up (spec §11 recording, "A voice-over is a recording with
/// no picture"). A camera recording (spec §11 CAM-4) then looks the camera
/// up — the named one, else the default, refused naming every camera present
/// — then its format (CAM-6), and only then the Camera grant (`+RecordingCamera.swift`); so
/// does a screen recording given a `camera` to record beside it (spec §11 CAM-10 (5)),
/// before anything screen-side. A
/// screen recording then reads the Screen Recording grant,
/// synchronously, named with the System Settings pane. Only then the
/// display or window lookup, which cannot be asked without the grant — a
/// list with NO display in it (a locked console) is named as that, not as
/// an index out of range. `CGRequestScreenCaptureAccess` and the picker are
/// never called, nor is System Settings opened (decision 4): the panel is
/// where a person grants.
///
/// **The target is `.document(recipeKey:)`**, resolved BEFORE the recording
/// and looked up again AFTER it (`RecordingLanding.resolve`): a document that
/// closed meanwhile lands as a new project and the answer says so, as it does
/// for `place: false` in a new project, which still opens the document.
        return trimmed.isEmpty ? nil : trimmed
    }

    /// CAM-4 points 2 and 3 with CAM-6 (6), as CAM-10 (5) amends them,
    /// called by `recordingSourceKind` right after `source`'s value: with
    /// source `voice_over`, the given ones of `camera`, `camera_format`,
    /// `camera_layout` and `camera_cutout` (CO-83 (a)) are refused together
    /// in the voice-over's words; with `screen`, the first of
    /// `camera_format`, `camera_layout` and `camera_cutout` given without
    /// `camera` is refused (a camera beside the screen is named by
    /// `camera`); with `camera`, the given ones of
    /// `cameraRefusedArguments` (a JSON null is not given, `scalarArg`'s
    /// rule) are refused together, in that order.
    func recordingCameraStrangers(_ a: [String: Any], kind: RecordingSourceKind) throws {
        let camera = try recordingCameraArgument(a)
        let format = try recordingCameraFormatArgument(a)
        // CO-83 (a): the landing's two, given when present and not a JSON null.
        let landing = ["camera_layout", "camera_cutout"].filter {
            a[$0] != nil && !(a[$0] is NSNull)
        }
        let given =
            [("camera", camera), ("camera_format", format)].filter { $0.1 != nil }.map(\.0)
            + landing
        guard kind != .voiceOver || given.isEmpty else {
            throw ToolError(
                message: "With source voice_over, " + given.joined(separator: ", ")
                    + " cannot be given — a voice-over records the microphone alone.")
        }
        let beside = (format != nil ? ["camera_format"] : []) + landing
        if kind == .screen, camera == nil, let first = beside.first {
            throw ToolError(
                message: "With source screen, \(first) needs camera — name the camera to "
                    + "record beside the screen.")
        }
        guard kind == .camera else { return }
        let strangers = Self.cameraRefusedArguments.filter { a[$0] != nil && !(a[$0] is NSNull) }
        guard strangers.isEmpty else {
            throw ToolError(
                message: "With source camera, " + strangers.joined(separator: ", ")
                    + " cannot be given — a camera recording records the camera alone, at the "
                    + "camera's own format.")
        }
    }

    /// `camera_layout` and `camera_cutout` (road map creator-jobs CO8, spec §11 CO-83 (b)), read
    /// after the polish and before any grant: the enum first (`enumArg` refuses an unknown value
    /// with the vocabulary), then with `place: false` a given layout and a true cutout, each in
    /// its sentence. Defaults `corner_square` and false: a tool reads no `UserDefaults`. With
    /// voice_over, or screen without camera, a given one never reaches here
    /// (`recordingCameraStrangers`).
    func recordingCameraLanding(_ a: [String: Any], place: Bool) throws
        -> (layout: RecordingCameraLayout, cutout: Bool)
    {
        let layout = try enumArg(a, "camera_layout", RecordingCameraLayout.self)
        let cutout = try boolArg(a, "camera_cutout") ?? false
        if !place, layout != nil {
            throw ToolError(
                message: "camera_layout lays out the landed camera clips, so it needs place: "
                    + "true.")
        }
        if !place, cutout {
            throw ToolError(
                message: "camera_cutout: true removes the landed camera clips' background, so it "
                    + "needs place: true.")
        }
        return (layout ?? .cornerSquare, cutout)
    }

